import heapq

def solution(input_text):
    lines = input_text.strip().split('\n')
    n, m = map(int, lines[0].split())

    edges = []
    adj = [[] for _ in range(n + 1)]

    for i in range(m):
        u, v, w = map(int, lines[1 + i].split())
        # Store edges with 1-based index
        edges.append((u, v, w, i + 1))
        adj[u].append((v, w, i + 1))
        adj[v].append((u, w, i + 1))

    start_vertex = int(lines[1 + m])

    # Dijkstra's algorithm to compute shortest distances from start_vertex
    dist = [float('inf')] * (n + 1)
    dist[start_vertex] = 0
    heap = [(0, start_vertex)]

    while heap:
        d, u = heapq.heappop(heap)

        if d > dist[u]:
            continue

        for v, w, idx in adj[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                heapq.heappush(heap, (dist[v], v))

    # Build shortest-path tree with minimum total edge weight
    total_weight = 0
    edge_indices = []

    # For each vertex v (except start), select one incoming edge (u, v)
    # such that dist[u] + weight = dist[v], minimizing the weight
    for v in range(1, n + 1):
        if v == start_vertex:
            continue

        best_edge_idx = -1
        best_weight = float('inf')

        # Check all edges where v is the destination
        for u, w, idx in adj[v]:
            if dist[u] != float('inf') and dist[u] + w == dist[v]:
                if w < best_weight:
                    best_weight = w
                    best_edge_idx = idx

        if best_edge_idx != -1:
            total_weight += best_weight
            edge_indices.append(best_edge_idx)

    # Output result
    result = f"{total_weight}\n"
    if edge_indices:
        result += " ".join(map(str, edge_indices)) + " "
    else:
        result += ""

    return result + "\n"


if __name__ == "__main__":
    import sys
    for line in sys.stdin:
        if line.strip():
            print(solution(line.strip()))

