def get_next_state(pattern, current_state, char):
    """
    Computes the new KMP state after seeing character 'char' starting from current_state.
    Returns the J such that the first J characters of pattern match the end of our string.
    If J == len(pattern), virus is formed, so we should avoid this state.
    """
    m = len(pattern)
    if m == 0:
        return 0

    # KMP failure function computation
    pi = [0] * m
    j = 0
    for i in range(1, m):
        while j > 0 and pattern[i] != pattern[j]:
            j = pi[j - 1]
        if pattern[i] == pattern[j]:
            j += 1
        pi[i] = j

    # Compute next state using KMP
    j = current_state
    while j > 0 and char != pattern[j]:
        j = pi[j - 1]

    if char == pattern[j]:
        return j + 1
    else:
        return j


