    def is_prime_mr(n):
        if n < 2:
            return False
        if n == 2 or n == 3:
            return True
        if n % 2 == 0:
            return False

        # Write n-1 as 2^r * d where d is odd
        r = 0
        d = n - 1
        while d % 2 == 0:
            d //= 2
            r += 1

        # Witnesses for Miller-Rabin (deterministic for n < 3*10^8)
        for a in [2, 3, 5, 7, 11]:
            if n <= a:
                break
            x = pow(a, d, n)
            if x == 1 or x == n - 1:
                continue
            for _ in range(r - 1):
                x = pow(x, 2, n)
                if x == n - 1:
                    break
            else:
                return False
        return True

    count = 0
    for i in range(l, r + 1):
        if is_prime_mr(i) and (i == 2 or i % 4 == 1):
            count += 1

    return str(count) + '\n'

