def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return '-1\n'

    first_line = lines[0].split()
    n = int(first_line[0])
    m = int(first_line[1])

    # Parse edges
    edges = []
    for i in range(1, m + 1):
        if i < len(lines):
            line_parts = lines[i].split()
            if len(line_parts) >= 2:
                u, v = int(line_parts[0]), int(line_parts[1])
                edges.append((u, v))

    # Build adjacency list
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    # Find connected components and their sizes
    visited = [False] * (n + 1)
    component_sizes = []

    def dfs(node):
        count = 0
        stack = [node]
        while stack:
            curr = stack.pop()
            if not visited[curr]:
                visited[curr] = True
                count += 1
                for neighbor in graph[curr]:
                    if not visited[neighbor]:
                        stack.append(neighbor)
        return count

    for i in range(1, n + 1):
        if not visited[i]:
            size = dfs(i)
            if size > 0:
                component_sizes.append(size)

    # Generate lucky numbers up to n
    lucky_numbers = []
    def generate_lucky(current):
        if current > n:
            return
        if current > 0:
            lucky_numbers.append(current)
        if current * 10 + 4 <= n:
            generate_lucky(current * 10 + 4)
        if current * 10 + 7 <= n:
            generate_lucky(current * 10 + 7)

    generate_lucky(0)
    lucky_numbers = sorted(set(lucky_numbers))
    lucky_numbers.sort()

    # If there's already a lucky component, answer is 0
    for size in component_sizes:
        if size in lucky_numbers:
            return '0\n'

    # DP to find minimum number of components to get each lucky total size
    # dp[i] = minimum number of components to get total size i
    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    for size in component_sizes:
        for i in range(n, size - 1, -1):
            if dp[i - size] != float('inf'):
                dp[i] = min(dp[i], dp[i - size] + 1)

    # Find minimum roads needed
    min_roads = float('inf')
    for lucky in lucky_numbers:
        if dp[lucky] != float('inf'):
            roads = dp[lucky] - 1  # Need (num_components - 1) roads to join components
            min_roads = min(min_roads, roads)

    if min_roads == float('inf'):
        return '-1\n'
    else:
        return str(min_roads) + '\n'


