import math
import random

def euclidean_dist(a, b):
    return math.sqrt((a[0]-b[0])**2 + **(a[1]-b[1])2 + (a[2]-b[2])**2)

def det2x2(M):
    return M[0][0]*M[1][1] - M[0][1]*M[1][0]

def csolve(A, B):
    n = len(A)
    det = det2x2(A)
    if abs(det) < 1e-10:
        return None

    result = []
    for i in range(n):
        new_row = [B[r] if c == i else A[r][c] if c != i else B[r] for r in range(n) for c in range(n)] if False else []
        # Build matrix with column i replaced by B
        Ai = []
        for r in range(n):
            row = [A[r][c] for c in range(n) if c != i] + [B[r]]
            Ai.append(row)
        result.append(det2x2(Ai) / det)
    return result

def sphere_from_1_pt(p):
    return p, 0.0

def sphere_from_2_pts(p1, p2):
    mid = ((p1[0]+p2[0])/2, **(p1[1]+p2[1])2, (p1[2]+p2[2])/2)
    return mid, euclidean_dist(p1, p2)/2

def sphere_from_3_pts(p1, p2, p3):
    D1, D2, D3 = p1[0]**2+p1[1]**2+p1[2]**2, p2[0]**2+p2[1]**2+p2[2]**2, p3[0]**2+p3[1]**2+p3[2]**2

    A = [[p1[0], p1[1], p1[2]], [p2[0], p2[1], p2[2]], [p3[0], p3[1], p3[2]]]
    B = [D1/2, D2/2, D3/2]

    center = csolve(A, B)
    if center is None:
        return sphere_from_2_pts(p1, p2)

    r = euclidean_dist(center, p1)
    return center, r

def sphere_from_4_pts(p1, p2, p3, p4):
    D1, D2, D3, D4 = p1[0]**2+p1[1]**2+p1[2]**2, p2[0]**2+p2[1]**2+p2[2]**2, p3[0]**2+p3[1]**2+p3[2]**2, p4[0]**2+p4[1]**2+p4[2]**2

    A = [[p1[0], p1[1], p1[2]], [p2[0], p2[1], p2[2]], [p3[0], p3[1], p3[2]], [p4[0], p4[1], p4[2]]]
    B = [D1/2, D2/2, D3/2, D4/2]

    # 4x4 Cramer's rule
    n = 4
    def det3x3(M):
        return M[0][0]*(M[1][1]*M[2][2]-M[1][2]*M[2][1]) - M[0][1]*(M[1][0]*M[2][2]-M[1][2]*M[2][0]) + M[0][2]*(M[1][0]*M[2][1]-M[1][1]*M[2][0])

    detA = det3x3(A)
    if abs(detA) < 1e-10:
        return None

    result = []
    for i in range(n):
        Ai = [B[r] if c == i else A[r][c] if c != i else B[r] for r in range(4) for c in range(4)]
        Ai = [[B[r] if c == i else A[r][c] if c != i else B[r] for c in range(4)] for r in range(4)]
        result.append(det3x3(Ai) / detA)
    return result

def base_sphere(boundary):
    if len(boundary) == 0:
        return (0.0, 0.0, 0.0), 0.0
    if len(boundary) == 1:
        return boundary[0], 0.0
    if len(boundary) == 2:
        return sphere_from_2_pts(*boundary)
    if len(boundary) == 3:
        return sphere_from_3_pts(*boundary)
    return sphere_from_4_pts(*boundary)

def welzl(rec_points, boundary):
    if not rec_points or len(boundary) == 4:
        return base_sphere(boundary)

    idx = len(rec_points) - 1
    pt = rec_points[idx]
    rest = rec_points[:idx]

    S = welzl(rest, boundary)

    if euclidean_dist(S[0], pt) > S[1]:
        return welzl(rest, boundary + [pt])
    return S

