        px, py = px, py
        g = gcd(px, py)
        vec = (px // g, py // g)
        vector_groups[vec].append(i)

    # Count valid pairings - points on same vector form a valid group
    # Number of ways to pick 2k points from m points is combinations(m, 2k)
    # We can count this properly with DP

    total_ways = 0
    cnt = 0

    def ways(n, k):
        if k > n or k < 0:
            return 0
        res = 1
