    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    e = list(map(int, lines[2].split()))

    import math
    from functools import reduce

    # Initial GCD of all a
    g = reduce(math.gcd, a)

    if g == 1:
        return "0"

    # Factorize g (keep only prime factors, not prime powers)
    prime_factors = []
    temp = g
    d = 2
    while d * d <= temp:
        while temp % d == 0:
            prime_factors.append(d)
            temp //= d
        d += 1
    if temp > 1:
        prime_factors.append(temp)

    m = len(prime_factors)

    # Build adjacency: which judges can handle each prime factor
    # A judge i can handle prime p if: p divides a[i] AND p <= k
    can_handle = set()
    for i in range(n):
        for p in prime_factors:
            if a[i] % p == 0 and p <= k:
                can_handle.add(i)

    if not can_handle:
        return "-1"

    # Greedy set cover: for each prime, find judge that can handle it with minimum exp
    selected = set()
    covered = {False} * m
    for p_idx in range(m):
        p = prime_factors[p_idx]
        best_j = -1
        best_e = float('inf')
        for j in range(n):
            if j not in selected and a[j] % p == 0 and p <= k:
                if e[j] < best_e:
                    best_e = e[j]
                    best_j = j

        if best_j == -1:
            return "-1"

        selected.add(best_j)

    count = len(selected) if selected > 0 else 1
    total_exp = sum(e[j] for j in selected) if selected else 100

    return str(count * total_exp)

