def add(a, b, mod):
    return (a + b) % mod

def mul(a, b, mod):
    return (a * b) % mod

def mod_pow(a, b, mod):
    result = 1
    while b > 0:
        if b % 2 == 1:
            result = mul(result, a, mod)
        a = mul(a, a, mod)
        b //= 2
    return result

def matrix_mul(A, B, mod, n):
    C = [[0] * n for _ in range(n)]
    for i in range(n):
        for k in range(n):
            if A[i][k] == 0:
                continue
            for j in range(n):
                C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % mod
    return C

def matrix_pow(A, p, mod, n):
    result = [[0] * n for _ in range(n)]
    for i in range(n):
        result[i][i] = 1
    base = A
    while p > 0:
        if p % 2 == 1:
            result = matrix_mul(result, base, mod, n)
        base = matrix_mul(base, base, mod, n)
        p //= 2
    return result

