        elif c == 'D':
            possible = [('D', 0)]

        for char, diff_change in possible:
            new_diff = current_diff + diff_change

            # Must stay within bounds before the last position
            if new_diff == k or new_diff == -k:
                # Reached k or -k, can only continue if this is the last position
                if pos == n - 1:
                    return char

