def solution(data):
    lines = data.strip().split('\n')
    n, m = map(int, lines[0].split())
    edges = []
    for i in range(1, m + 1):
        ai, bi = map(int, lines[i].split())
        edges.append((ai, bi))

    # Normalize edges so a < b (for interval comparison)
    normalized = []
    for (a, b) in edges:
        if a < b:
            normalized.append((a, b))
        else:
            normalized.append((b, a))

    def intersects(i, j):
        """Check if two edges cross (intersect only in interior, not at shared endpoints)"""
        a1, b1 = normalized[i]
        a2, b2 = normalized[j]

        # If they share a vertex, they don't cross in the interior
        if a1 == a2 or a1 == b2 or b1 == a2 or b1 == b2:
            return False

        # Edge crosses if one endpoint of edge2 is in (a1,b1) and the other is outside
        a2_in = (a1 < a2 < b1)
        b2_in = (a1 < b2 < b1)

        return a2_in != b2_in

    # Build conflict graph (edges that cross form edges in the graph)
    adj = [[] for _ in range(m)]
    for i in range(m):
        for j in range(i + 1, m):
            if intersects(i, j):
                adj[i].append(j)
                adj[j].append(i)

    # Check if graph is bipartite using BFS
    color = [-1] * m
    possible = True

    for start in range(m):
        if color[start] == -1:
            color[start] = 0
            queue = [start]
            while queue and possible:
                u = queue.pop(0)
                for v in adj[u]:
                    if color[v] == -1:
                        color[v] = 1 - color[u]
                        queue.append(v)
                    elif color[v] == color[u]:
                        possible = False

    if not possible:
        return "Impossible"
    else:
        return ''.join('i' if c == 0 else 'o' for c in color) + '\n'


