def solution(input_str):
    MOD = 10**9 + 7

    lines = input_str.strip().split('\n')
    if not lines:
        return ''

    q = int(lines[0])
    queries = []
    for line in lines[1:]:
        if line.strip():
            r, n = map(int, line.split())
            queries.append((r, n))

    if not queries:
        return ''

    max_n = max(n for _, n in queries)

    # Precompute smallest prime factor (SPF)
    spf = list(range(max_n + 1))
    for i in range(2, int(max_n**0.5) + 1):
        if spf[i] == i:
            for j in range(i*i, max_n + 1, i):
                if spf[j] == j:
                    spf[j] = i

    # omega[n] = number of distinct prime factors
    omega = [0] * (max_n + 1)
    for i in range(2, max_n + 1):
        if spf[i] != i:
            omega[i] = omega[i // spf[i]] + 1

    # f0(n) = 2^omega(n)
    def f0(n):
        if n == 1:
            return 1
        return pow(2, omega[n], MOD)

    # Precompute divisors
    divisors = [[] for _ in range(max_n + 1)]
    for i in range(1, max_n + 1):
        for j in range(i, max_n + 1, i):
            divisors[j].append(i)

    memo = {}

    def compute_fr(r, n):
        key = (r, n)
        if key in memo:
            return memo[key]

        if r == 0:
            result = f0(n)
        else:
            # fr(n) = sum(fr-1(d)) for all divisors d of n
            result = 0
            for d in divisors[n]:
                result = (result + compute_fr(r - 1, d)) % MOD

        memo[key] = result
        return result

    results = [str(compute_fr(r, n)) for r, n in queries]
    return '\n'.join(results)

