def intersect(p1, q1, p2, q2):
    """Check if segments p1q1 and p2q2 intersect or touch"""
    def ccw(A, B, C):
        val = (B[0] - A[0]) * (C[1] - A[1]) - (B[1] - A[1]) * (C[0] - A[0])
        return val

    def on_segment(p1, p2, p3):
        return min(p1[0], p2[0]) <= p3[0] <= max(p1[0], p2[0]) and \
               min(p1[1], p2[1]) <= p3[1] <= max(p1[1], p2[1])

    d1 = ccw(p1, q1, p2)
    d2 = ccw(p1, q1, q2)
    d3 = ccw(p2, q2, p1)
    d4 = ccw(p2, q2, q1)

    if ((d1 > 0 and d2 < 0) or
       (d1 < 0 and d2 > 0)) and \
       ((d3 > 0 and d4 < 0) or (d3 < 0 and d4 > 0)):
        return True

    if d1 == 0 and on_segment(p1, q1, p2): return True
    if d2 == 0 and on_segment(p1, q1, q2): return True
    if d3 == 0 and on_segment(p2, q2, p1): return True
    if d4 == 0 and on_segment(p2, q2, q1): return True

    return False


