    best_idx = 0
    best_cost = float('inf')

    for i in range(n):
        val = a[i]
        # Operations to flip from positive to negative (cross 0)
        if val == 0:
            ops_to_flip = 0
        else:
            ops_to_flip = (abs(val) + x - 1) // x

        if ops_to_flip < best_cost:
            best_cost = ops_to_flip
            best_idx = i

    remaining_k = k
    ops_to_apply = min(remaining_k, best_cost)

    # Apply operations to flip and minimize the best element
    if best_cost > 0:
        a[best_idx] = ((abs(a[best_idx]) % x) - x) if a[best_idx] > 0 else (abs(a[best_idx]) - (ops_to_apply * x)) if a[best_idx] < 0 else 0
        remaining_k -= ops_to_apply

    # Use remaining operations to minimize absolute value (make as close to 0 as possible)
    while remaining_k > 0 and abs(a[best_idx]) >= x:
        if a[best_idx] > 0:
            a[best_idx] -= x
        else:
            a[best_idx] += x
        remaining_k -= 1

    # If we still have operations and element is not 0, optimize further
    if remaining_k > 0 and abs(a[best_idx]) < x and a[best_idx] != 0:
        if a[best_idx] > 0:
            a[best_idx] -= x
        else:
            a[best_idx] += x
        remaining_k -= 1

    return ' '.join(map(str, a)) + '\n'

