from math import gcd

def solution(s):
    parts = s.strip().split()
    n = int(parts[0])
    l = int(parts[1])
    r = int(parts[2])

    if n == 1:
        return str(r - l + 1) + '\n'
    elif n == 2:
        return str((r - l + 1) * (r - l)) + '\n'
    else:
        ans = 0
        for q in range(1, r + 1):
            q_pow = q ** (n - 1)
            if q_pow > r * 1000:
                break

            # For p < 2q + 1 covers reasonable ratios
            p_end = 2 * q + 1 if q > 1 else r + 1
            p_end = min(p_end, r)

            for p in range(1, p_end + 1):
                if gcd(p, q) != 1 or p == q:
                    continue

                p_pow = p ** (n - 1)

                if p >= q:
                    # Progression is non-decreasing
                    min_a = (l * q_pow + p_pow - 1) // p_pow
                    max_a = (r * q_pow) // p_pow
                else:
                    # Progression is non-increasing
                    min_a = (l * q_pow + p_pow - 1) // p_pow
                    max_a = (r * q_pow) // p_pow

                if min_a > max_a:
                    continue

                first = ((min_a + q_pow - 1) // q_pow) * q_pow
                last = (max_a // q_pow) * q_pow

                if first <= last:
                    ans += (last - first) // q_pow + 1

        return str(ans) + '\n'

