import math

def solution(nm):
    n, m = map(int, nm.split())
    roots = set()

    # For each b, c ranges from 1 to min(m, b^2)
    # Make sure not to duplicate the root when discriminant is 0

    for b in range(1, n + 1):
        max_c = m if m < b * b else b * b

        for c in range(1, max_c + 1):
            D = b * b - c
            if D == 0:
                roots.add(-b)
            else:
                sqrt_D = math.isqrt(D)
                # If sqrt_D^2 < D, it's not a perfect square
                # For irrational roots, they're always distinct
                roots.add(-b - sqrt_D)
                roots.add(-b + sqrt_D)

    return str(len(roots))
